def merge_sorted(a: list, b: list) -> list:
    i, j = 0, 0
    res = []
    n, m = len(a), len(b)
    while i < n and j < m:
        if a[i] <= b[j]:
            res.append(a[i])
            i += 1
        else:
            res.append(b[j])
            j += 1
    while i < n:
        res.append(a[i])
        i += 1
    while j < m:
        res.append(b[j])
        j += 1
    return res
